# -*- coding: utf-8 -*-
import os
import time
from taf.sw.dcap.rd import rd
from robot.api import logger
from taf.rfrl.cbts.utilities import tl_config
from taf.rfrl.cbts.utilities import generic_utils

LOG_HEAD = LOG_END = '*' * 8


class DcapBasicCollector(object):
    """
    Usage example:

    # python
    >>> from taf.rfrl.cbts.devices.dcap_basic.dcap import DcapBasicCollector
    >>> dcap = DcapBasicCollector()

    >>> dcap.connect_to_dcap(host='10.44.1.1', port='443', username='dcapuser', password='dcapadmin!', conn_alias='dcap_collector')

    >>> trace_id = dcap.start_dcap_trace(ne_type='vdu', nr_cell_list=['MRBTS-108281/NRBTS-10828/NRCELL-1'], vdu_custom_profile=['L2Ps_Component'],
                                         conn_alias='dcap_collector')

    >>> dcap.stop_dcap_trace(trace_id, conn_alias='dcap_collector')
    >>> zip_path = dcap.download_logs_file(trace_id, conn_alias='dcap_collector', target_dir='/tmp/dcap_logs')
    >>> dcap.teardown()

    #RobotFramework
    Library       taf.rfrl.cbts.devices.dcap_basic.dcap.DcapBasicCollector   WITH NAME   dcap_api

    *** Test Cases ***
    DCAP Log Collector
        [Tags]    dcap
        ${Target_Cells_DN_List}=   create list   MRBTS-108281/NRBTS-10828/NRCELL-1
        ${VDU_Log_Profile}=  Create List  L2Ps_Component
        dcap_api.connect_to_dcap
        ...  host=10.107.169.186
        ...  username=dcapuser
        ...  password=dcapadmin!
        ...  conn_alias=dcap_collector
        ${Trace_ID}=  dcap_api.start_dcap_trace
        ...  ne_type=vdu
        ...  nr_cell_list=${Target_Cells_DN_List}
        ...  conn_alias=dcap_collector
        ...  bts_alias=5gvDU-10828
        ...  vdu_custom_profile=${VDU_Log_Profile}
        sleep  10s
        dcap_api.stop_dcap_trace
        ...  trace_id=${Trace_ID}
        ...  conn_alias=dcap_collector
        ${trace_zip_file}=  dcap_api.download_logs_file
        ...  trace_id=${Trace_ID}
        ...  conn_alias=dcap_collector
        [Teardown]  dcap_api.teardown
    """
    _dcap_api = rd()

    def __init__(self):
        self._active_connections = {}
        self._bts_to_be_deleted = []

    def _assert_connection(self, alias):
        if alias not in self._active_connections:
            raise ConnectionError("Alias {alias} is not connected! Have you called 'connect_to_dcap' method?".format(alias=alias))

    def connect_to_dcap(self, host, port='443', username='dcapuser', password='dcapadmin!',
                        rd_version='dcapv3', secure=True, conn_alias='dcap_collector'):
        """
        Connect to DCAP Basic.
        If the DCAP already is connected by this keyword, new connection will not be set up.
        All bts info which connected to the DCAP will be stored by the keywords.

        :param str host: the host ip of DCAP API.
        :param str port: port of DCAP API.
        :param str username: username of DCAP.
        :param str password: password of DCAP.
        :param str rd_version: DCAP version. Default is dcapv3.
        :param bool secure: A flag of using http or https. Default is true which means using https.
        :param str conn_alias: connection alias. Default is dcap_collector.
        :return: None
        """
        if conn_alias in self._active_connections:
            logger.info("{} DCAP connection with alias {} already existed. No need to set up new connection {}".format(LOG_HEAD, alias, LOG_END))
            return
        logger.info("{log_head} Connecting to DCAP basic on {host}:{port}, user = {user}, password = {passwd} {log_end}".format(
            log_head=LOG_HEAD, host=host, port=port, user=username, passwd=password, log_end=LOG_END
        ))
        self._dcap_api.connect_to(host=host, port=port, username=username, password=password,
                                  rd_version=rd_version, secure=secure, alias=conn_alias)
        self._active_connections[conn_alias] = self._dcap_api.get_all_bts_info(connection=conn_alias)
        logger.info("{} All BTS info {} \n {}".format(LOG_HEAD, LOG_END, self._active_connections[conn_alias]))

    @staticmethod
    def _get_ne_credentials(ne_type, gnb_index=0, vdu_index=0):
        if ne_type.lower() == 'vdu':
            vdu_webem_credentials = tl_config.get_vdu_webem_credentials(gnb_index=gnb_index,
                                                                        vdu_index=vdu_index)
            oam_host = vdu_webem_credentials['ip']
            oam_username = vdu_webem_credentials['username']
            oam_password = 'Nokia@123'
            return oam_host, oam_username, oam_password
        if ne_type.lower() == 'vcu':
            vcu_webem_credentials = tl_config.get_vcu_webem_credentials(gnb_index=gnb_index)
            oam_host = vcu_webem_credentials['ip']
            oam_username = vcu_webem_credentials['username']
            oam_password = 'Nokia@123'
            return oam_host, oam_username, oam_password

    def create_bts_to_dcap(self, host, username, password, conn_alias='dcap_collector', port='443', bts_alias='target_bts'):
        """
        integrate bts to DCAP.

        :param str host: bts oam ip.
        :param str username: bts oam username.
        :param str password: bts oam password.
        :param str conn_alias: connection alias. Default is dcap_collector.
        :param str port: bts oam port, default is 443.
        :param str bts_alias: bts alias, default is target_bts.
        :return str: bts information.
        """
        for bts in self._active_connections[conn_alias]:
            if host == bts['host']:
                return bts
        logger.info("{} Creating BTS: {}, {}, {}, {} {}".format(LOG_HEAD, host, port, username, password, LOG_END))
        bts_obj = self._dcap_api.create_bts(host=host, port=port, username=username, password=password, connection=conn_alias, bts_alias=bts_alias)
        self._bts_to_be_deleted.append((conn_alias, bts_obj.id))
        bts = bts_obj.to_dict()
        return bts

    @staticmethod
    def _validate_target_cells_list(bts_cells, target_cells):
        matched_cells_dn = [bts_cell['internal_id'] for target_cell in target_cells for bts_cell in bts_cells
                            if bts_cell['internal_id'] == target_cell]
        if len(matched_cells_dn) != len(target_cells):
            raise ValueError("Target cells dn {}, matched cells dn {}\n, all cells {}".format(target_cells, matched_cells_dn, bts_cells))
        return matched_cells_dn

    def start_dcap_trace(self, ne_type, nr_cell_list, conn_alias='dcap_collector', ne_oam_port='443', bts_alias='target_bts', force=False,
                         gnb_index=0, vdu_index=0, **kwargs):
        """
        Starts new trace for specified bts

        :param str ne_type: NE type, only support vdu or vcu by now. Case insensitive.
        :param list nr_cell_list: NR cell DN list.
        :param str conn_alias: connection alias. Default is dcap_collector.
        :param str ne_oam_port: NE oam port which used to create bts and start strace in DCAP. Default is 443.
        :param str bts_alias: BTS alias which used to create bts in DCAP. Default is target_bts.
        :param bool force: Signifying whether the trace should force a shutdown of any previously running traces.
                           If the trace startup finds an ongoing trace and 'force' is set to false,
                           the startup fails due to ongoing traces error.
                           If the 'force' flag is set to true, the startup first shuts down any ongoing traces and then continues with the startup,
                           Default value is "False".
        :param int gnb_index: gnb index in testline __init__.py which is used to get the NE oam credentials. Default is 0.
        :param int vdu_index: vdu index in testline __init__.py which is used to get the NE oam credentials. Default is 0.
        :param kwargs: kwargs are used to pass log profile. e.g.
                       vdu_custom_profile=['L2Ps_Component']
                       vcu_custome_profile=['L2HiRlc_Component']
        :return str: the id of started trace.
        """
        self._assert_connection(conn_alias)
        oam_host, oam_username, oam_password = self._get_ne_credentials(ne_type=ne_type, gnb_index=gnb_index, vdu_index=vdu_index)
        created_bts = self.create_bts_to_dcap(host=oam_host, username=oam_username, password=oam_password,
                                              conn_alias=conn_alias, port=ne_oam_port, bts_alias=bts_alias)
        nr_cells_dn_list = self._validate_target_cells_list(created_bts['nr_cells'], nr_cell_list)
        bts_info = {'host': oam_host, 'port': ne_oam_port, 'username': oam_username, 'password': oam_password, 'nrCells': nr_cells_dn_list}
        pre_check = self._dcap_api.check_precondition(bts=bts_info, connection=conn_alias, **kwargs)
        if not pre_check:
            raise Exception("DCAP trace precondition check failed with msg: {}.".format(pre_check.msgs))
        logger.info("{} Starting to collect DCAP trace on {}, NR cells: {}, log profile {} {}".format(
            LOG_HEAD, oam_host, nr_cells_dn_list, kwargs, LOG_END))
        trace_id = self._dcap_api.start_trace(bts_info, connection=conn_alias, force=force, **kwargs)['tracer_id']
        logger.info("{} Trace started successfully. ID = {} {}".format(LOG_HEAD, trace_id, LOG_END))
        return trace_id

    def _wait_for_statuses(self, trace_id, expected_statuses, conn_alias='dcap_collector', timeout=700):
        end_time = time.time() + timeout
        while time.time() < end_time:
            time.sleep(1)
            trace_info = self._dcap_api.get_trace_info_by_id(trace_id=trace_id, connection=conn_alias)
            if trace_info['status'] in expected_statuses:
                return
        else:
            trace_info = self._dcap_api.get_trace_info_by_id(trace_id=trace_id, connection=conn_alias)
            raise RuntimeError(
                "status {current_status} not in "
                "expected statuses {expected_statuses} "
                "for trace_id {trace_id} "
                "after {timeout} seconds timeout".format(
                    current_status=trace_info['status'],
                    expected_statuses=expected_statuses,
                    trace_id=trace_id,
                    timeout=timeout))

    def stop_dcap_trace(self, trace_id, conn_alias='dcap_collector', timeout=600):
        """
        Stop dcap trace by given trace_id. Trace_id is obtained from start_dcap_trace kw.

        :param str trace_id: id of trace to stop. Returned value fro start_dcap_trace kw.
        :param str conn_alias: alias given to dcap in 'connect_to_dcap' keyword.
        :return: None
        """

        self._assert_connection(conn_alias)
        trace_info = self._dcap_api.get_trace_info_by_id(trace_id=trace_id, connection=conn_alias)
        if trace_info["status"] not in ['ready', 'readyWithWarnings', 'aborted', 'failed']:
            logger.info("{} Stoping dcap trace with id = {} {}".format(LOG_HEAD, trace_id, LOG_END))
            self._dcap_api.stop_trace(trace_id=trace_id, connection=conn_alias, timeout=timeout)
            self._wait_for_statuses(trace_id=trace_id, expected_statuses=['ready'], conn_alias=conn_alias)
            # return result
        else:
            logger.info("{} Trace id {} is under {} {}".format(LOG_HEAD, trace_id, trace_info["status"], LOG_END))

    def download_logs_file(self, trace_id, conn_alias='dcap_collector', target_dir=None, timeout=600):
        """
        Download collected zip with results from DCAP

        :param str trace_id: id of trace to download results of. Returned value from start_dcap_trace kw.
        :param str conn_alias: alias given to dcap in 'connect_to_dcap' keyword.
        :param str target_dir: path to directory to which zip will be collected. If path not exists,
                               creates such directory. Raises error if path exists but is not a direcotry.
                                     Defaults to '/tmo/dcap_logs'.
        :param int timeout: timeout for downloading files. (defaults to 600 sec)
        :returns str: path to collected zip
        """
        self._assert_connection(conn_alias)
        if target_dir:
            dcap_log_folder = target_dir
        else:
            dcap_log_folder = generic_utils.generate_log_path_with_log_type(log_type='dcap_logs')

        if not os.path.exists(dcap_log_folder):
            os.makedirs(dcap_log_folder)

        trace_info = self._dcap_api.get_trace_info_by_id(trace_id=trace_id, connection=conn_alias)
        if trace_info["status"] == 'ready':
            return self._dcap_api.get_results(result_id=trace_id, target_dir=dcap_log_folder, timeout=timeout, connection=conn_alias)
        else:
            logger.info("{} The status of trace {} is {}, can not save logs {}".format(LOG_HEAD, trace_id, trace_info['status'], LOG_END))

    def teardown(self):
        """
        This method deletes all bts from DCAP that were added by this library.
        """

        for connection, bts_id in self._bts_to_be_deleted:
            self._dcap_api.delete_bts(bts_id=bts_id, connection=connection)

    def get_dcap_bts_id(self, bts_host, conn_alias='dcap_collector'):
        """
        get bts id which is integrated in DCAP by bts ip.

        :param str bts_host: bts ip.
        :param str conn_alias: alias given to dcap in 'connect_to_dcap' keyword.
        :return str: bts id.
        """
        dcap_bts_info = self._dcap_api.get_all_bts_info(connection=conn_alias)
        for bts in dcap_bts_info:
            if bts_host == bts['host']:
                return bts['id']

    def delete_bts_from_dcap(self, bts_host, conn_alias='dcap_collector'):
        """
        delete bts from DCAP.

        :param str bts_host: bts ip.
        :param str conn_alias: alias given to dcap in 'connect_to_dcap' keyword.
        :return: None
        """
        bts_id = self.get_dcap_bts_id(bts_host=bts_host, conn_alias=conn_alias)
        if bts_id:
            self._dcap_api.delete_bts(bts_id=bts_id, connection=conn_alias)

    def delete_trace_in_dcap(self, trace_id, conn_alias='dcap_collector'):
        """
        delete trace in DCAP.

        :param str trace_id: trace id.
        :param str conn_alias: alias given to dcap in 'connect_to_dcap' keyword.
        :return str: the status of deleting trace.
        """
        result = self._dcap_api.delete_trace(trace_id=trace_id, connection=conn_alias)
        return result
